INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000000333', 'radical', '牙', 'fang', 31, 0, 'Bayangkan ini di mulut Anda. Itu adalah satu gigi yang paling menonjol dibandingkan gigi lainnya. Itu taringmu. Dapatkah Anda melihat ini keluar dari mulut serigala? Cobalah jika Anda tidak dapat membayangkan diri Anda memiliki taring sekeren ini.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000334', 'radical', '並', 'line-up', 31, 1, 'Radikal ini sama dengan kanji. Artinya berbaris.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000336', 'radical', '鬲', 'bully', 31, 2, 'Dia menjalar dan dia Four-T (empat puluh). Jika orang seperti ini merinding pada Anda, dia hanya pengganggu. Ketika Anda mencapai usia empat puluh, Anda tidak seharusnya lagi mengganggu orang lain. Anda pengganggu. Anda brengsek.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000337', 'radical', '离', 'rocket', 31, 3, 'Ini adalah radikal yang sangat rumit dan tinggi. Ada penutup di atasnya untuk menahan bahan peledak. Itu juga berisi harta karun, setidaknya bagi orang yang akan menerima apa yang ada di dalamnya. Juga, ia memiliki seekor sapi, yang akan digunakan untuk susu di Mars. Ini adalah roket yang berisi barang-barang untuk manusia luar angkasa.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000338', 'radical', '扁', 'library', 31, 4, 'Ada pintu di atas rak buku. Itu menjadikan ini perpustakaan!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000340', 'radical', '卬', 'cat-pirate', 32, 0, 'Lihat CP di radikal ini? Itu singkatan dari Bajak Laut Kucing. Meoaarrr.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000341', 'radical', '同', 'same', 32, 1, 'Radikal ini sama dengan kanji. Artinya sama.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000342', 'radical', '夜', 'night', 32, 2, 'Radikal ini sama dengan kanji. Artinya malam.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000343', 'radical', '必', 'certain', 32, 3, 'Radikal ini sama dengan kanji. Artinya pasti.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000344', 'radical', '間', 'interval', 33, 0, 'Radikal ini sama dengan kanji. Artinya interval.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000345', 'radical', '享', 'sock', 33, 1, 'Cara terbaik untuk menutup mulut anak adalah dengan memasukkan kaus kaki ke dalam mulut anak tersebut. Diamkan mereka dengan baik, itu benar. Tambahkan kaus kaki gemuk yang bagus dan mereka tidak dapat berbicara lagi, yang pada dasarnya menutup mulut mereka.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000346', 'radical', '内', 'inside', 33, 2, 'Radikal ini sama dengan kanji. Artinya di dalam.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000347', 'radical', '蔵', 'storehouse', 33, 3, 'Bungamu menjadi pelayanmu. Anda menanamnya, Anda menyiraminya, Anda membesarkannya, lalu Anda menebangnya dan menaruhnya di gudang Anda. Mereka melakukan apa yang Anda inginkan karena mereka menjadi hamba ANDA, bukan sebaliknya. Itu sebabnya Anda bisa menyuruh mereka duduk di gudang tempat mereka menunggu sampai Anda datang untuk memakannya.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000348', 'radical', '呉', 'catapult', 34, 0, 'Lihat batu di ketapel? Ia bahkan mempunyai kaki kecil untuk menahannya agar tetap stabil sehingga dapat melontarkan lebih baik.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000349', 'radical', '員', 'member', 34, 1, 'Radikal ini sama dengan kanji. Artinya anggota.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000350', 'radical', '爪', 'claw', 34, 2, 'Ini sudah terlihat seperti cakar, membuatnya cukup mudah!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000351', 'radical', '亥', 'slice', 34, 3, 'Lihat pria itu? Lihat bagaimana dia dipotong setengah??? Itu pasti merupakan tindakan yang sangat kejam untuk melakukan hal itu pada seseorang.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000352', 'radical', '帯', 'belt', 35, 0, 'Radikal ini sama dengan kanji. Artinya sabuk.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000353', 'radical', '亀', 'turtle', 35, 1, 'Ada cangkang kura-kura di dalam radikal kura-kura ini. Anda dapat mengetahuinya karena terdapat kepala dan ekor utuh pada benda ini, menjadikannya kura-kura asli, bukan hanya cangkang kura-kura.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000354', 'radical', '彑', 'shuriken', 35, 2, 'Lihat shurikennya tertancap di tanah? Jika Anda belum mengetahuinya, shuriken hanyalah bintang lempar. Ninja hebat menggunakannya. Itulah yang ada dalam radikal ini.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000355', 'radical', '為', 'sake', 35, 3, 'Radikal ini terlihat seperti serangga ulat yang besar dan aneh. Tapi, demi kewarasan semua orang, kita sebut saja demi, oke? Perlu diingat, yang kami maksud adalah sake seperti dalam "demi X", bukan seperti dalam minuman beralkohol!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000357', 'radical', '明', 'bright', 36, 0, 'Radikal ini sama dengan kanji. Artinya cerah.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000358', 'radical', '貴', 'valuable', 36, 1, 'Radikal ini sama dengan kanji. Artinya berharga.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000359', 'radical', '発', 'departure', 36, 2, 'Radikal ini sama dengan kanji. Artinya keberangkatan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000360', 'radical', '甘', 'sweet', 36, 3, 'Radikal ini adalah matahari dengan rambutnya yang mencuat. Mengapa rambut matahari mencuat seperti ini? Ia memakan terlalu banyak makanan manis yang menyebabkannya memiliki terlalu banyak energi, membuat bulunya berdiri. Bentuknya juga seperti permen yang manis dan manis dengan bungkusnya yang menonjol. Ingatlah sesuai keinginan Anda.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000361', 'radical', '南', 'south', 36, 4, 'Radikal ini sama dengan kanji. Artinya selatan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000363', 'radical', '兆', 'omen', 37, 0, 'Ada ledakan di sekitar kakimu. Seperti yang diperingatkan oleh peramal. Ini adalah pertanda yang dia bicarakan. Pikirkan tentang apa yang terjadi setelah pertanda itu muncul. Keajaiban peramal mengerikan apa yang akan terjadi???', NULL, NULL),
  ('00000000-0000-4000-8000-000000000364', 'radical', '賞', 'prize', 37, 1, 'Radikal ini sama dengan kanji. Artinya hadiah.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000365', 'radical', '串', 'skewer', 37, 2, 'Ada sebatang tongkat menembus daging yang berair. Ini tusuk sate.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000366', 'radical', '暴', 'violence', 37, 3, 'Radikal ini sama dengan kanji. Artinya kekerasan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000367', 'radical', '辟', 'hot-pepper', 38, 0, 'Anda melihat sesuatu dengan bendera di atasnya dan memasukkannya ke dalam mulut Anda. Rasanya pedas! Anda melihat bendera kecil dan tertulis... cabai.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000368', 'radical', '思', 'think', 38, 1, 'Radikal ini sama dengan kanji. Artinya berpikir.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000369', 'radical', '県', 'prefecture', 38, 2, 'Radikal ini sama dengan kanji. Artinya prefektur.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000370', 'radical', '空', 'sky', 38, 3, 'Radikal ini sama dengan kanji. Artinya langit.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000371', 'radical', '有', 'have', 38, 4, 'Radikal ini sama dengan kanji. Artinya punya.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000372', 'radical', '歯', 'tooth', 38, 5, 'Radikal ini sama dengan kanji. Artinya gigi.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000373', 'radical', '君', 'buddy', 39, 0, 'Radikal ini sama dengan kanji. Artinya sobat.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000374', 'radical', '旧', 'former', 39, 1, 'Radikal ini sama dengan kanji. Artinya mantan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000375', 'radical', '六', 'six-375', 39, 0, 'Ini sama dengan kanji Enam.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000376', 'radical', '岡', 'hill', 39, 2, 'Radikal ini sama dengan kanji. Artinya bukit.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000377', 'radical', '三', 'three', 39, 3, 'Radikal ini sama dengan kanji. Artinya tiga.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000378', 'radical', '雇', 'employ', 40, 0, 'Radikal ini sama dengan kanji. Artinya mempekerjakan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000379', 'radical', '毎', 'every', 40, 2, 'Radikal ini sama dengan kanji. Artinya setiap.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000380', 'radical', '保', 'preserve', 40, 3, 'Radikal ini sama dengan kanji. Artinya melestarikan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000382', 'radical', '広', 'wide', 33, 4, 'Radikal ini sama dengan kanji. Artinya luas.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000395', 'radical', '包', 'wrap', 37, 4, 'Diri Anda (diri sendiri) berada di penjara. Lihatlah penjara yang menyelimuti Anda. Itu membungkusmu dan memelukmu erat-erat. Itu sebabnya ini disebut radikal!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000413', 'radical', '真', 'reality', 39, 4, 'Radikal ini sama dengan kanji. Itu berarti kenyataan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000414', 'radical', '巻', 'scroll', 39, 5, 'Radikal ini sama dengan kanji. Artinya gulir.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000427', 'radical', '夋', 'spider', 32, 4, 'Jika Anda perhatikan lebih dekat dan hati-hati, terkadang Anda dapat melihat beberapa kaki pribadi di musim dingin. Kaki siapa? Kaki laba-laba! Cuacanya terlalu dingin bagi mereka di musim dingin, jadi mereka bersembunyi di celah-celah dan celah-celah, namun terkadang Anda masih bisa melihat kaki kecil mereka mencuat.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000428', 'radical', '堇', 'boot', 34, 4, 'Ada sesuatu yang terbuat dari kulit dengan sedikit kotoran di bagian bawahnya. Itu sepatu bot!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000429', 'radical', '舛', 'dance', 36, 5, 'Anda melihat seekor sapi di malam hari. Anda semakin dekat dan menyadari itu sedang menari. Semua sapi menari di malam hari. Bisakah Anda membayangkannya? Sapi itu menari, begitu megah, di bawah sinar matahari terbenam.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000430', 'radical', '㐮', 'nurse', 39, 6, 'Radikal ini terdiri dari blackjack dan pakaian dengan enam kanji di atasnya. Jika Anda melihat enam orang bermain blackjack dan mengenakan pakaian yang sama, Anda harus tahu bahwa mereka semua adalah perawat. Perawat bermain blackjack bersama untuk menenangkan diri di sela-sela shift dan mereka biasanya tidak punya waktu untuk mengganti seragam mereka. Itu sebabnya radikal ini adalah perawat.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000433', 'radical', '舎', 'cottage', 32, 5, 'Radikal ini tampak seperti sebuah rumah kecil, yang sempurna di antah berantah, dikelilingi bambu dan aliran sungai kecil di pegunungan. Lihat atap dan pintu yang terbuka? Itu sebabnya ini adalah pondok radikal.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000496', 'kanji', '久', '久', 32, 7, 'Jika Anda menggunakan perosotan untuk memasuki suatu bangunan, Anda akan meluncur dalam waktu yang lama.', 'Anda meluncur begitu lama hingga Anda merasa lapar. Untungnya, sesekali ada mentimun (きゅう) yang jatuh dari perosotan di sebelah Anda.', NULL),
  ('00000000-0000-4000-8000-000000001443', 'kanji', '離', '離', 31, 6, 'The rocket turkey has several points which will detach during takeoff.', 'When the rocket turkey parts detach, they fall to the ground onto a bed of reeds (り).', NULL),
  ('00000000-0000-4000-8000-000000001444', 'kanji', '融', '融', 31, 7, 'You see a bully take an insect and dissolve it in some acid. Bullies are messed up, mean people. They do awful things that normal kids and people wouldn''t do... like dissolve a living creature.', 'The only bullies heartless enough to dissolve insects like this are youths (ゆう). Do you really think an adult would melt a harmless critter? No. Only inexperienced youths could be so cruel.', NULL),
  ('00000000-0000-4000-8000-000000001445', 'kanji', '編', '編', 31, 8, 'Bring thread to the library to knit. Libraries are quiet and generally pretty empty nowadays, so it''s the perfect place to relax and do some knitting. Of course, if you find thread lying around in a library you know what to do now.', 'You need to come to the library to knit because if you try to do it at home all your hens (へん) will try to eat the thread. Hens love eating things that look like worms, like hay, string, and thread. So it''s important to get far away from them before you start to knit.', NULL),
  ('00000000-0000-4000-8000-000000001446', 'kanji', '華', '華', 31, 9, 'Flowers growing out of a rice paddy into the shape of a cross are really showy flowers.', 'These flowers are too showy. You hate them. You hate these showy flowers so much you run them over with your car (か)!', NULL),
  ('00000000-0000-4000-8000-000000001447', 'kanji', '既', '既', 31, 10, 'There''s a root where your fang previously was. Your fang isn''t there anymore, you ripped it out.', 'To remember the beautiful fangs you previously had, you keep all of the ones you pull out in a box you lock with a key (き).', NULL),
  ('00000000-0000-4000-8000-000000001448', 'kanji', '普', '普', 31, 11, 'You line up your body with the sun and everything looks normal.  The sun is lined up behind you, and you’re looking at all the things the sun has lit up. Everything looks normal.', 'Soon you see something that doesn’t look so normal. It’s a fool (ふ), a jester. Dressed all in fool’s garb, this fool is dancing up towards you with a ridiculously unsettling grin on his face.', NULL),
  ('00000000-0000-4000-8000-000000001449', 'kanji', '豪', '豪', 31, 12, 'You put a lid on a dish you''re cooking, made up of the mouths and foreheads of a pig. This is truly and exceptional dish you are cooking up.', 'Exceptional pig mouth forehead soup is a favorite of Grandpa ごういち. You see him sniffing around your window, then he knocks and waves.', NULL),
  ('00000000-0000-4000-8000-000000001450', 'kanji', '鑑', '鑑', 31, 13, 'You are given some gold to oversee a model. You are a famous architect, so you get a lot of gold for overseeing the construction of models like this one.', 'As the model nears completion, you realize it''s taking the shape of Genghis Khan (かん). Was that what this was supposed to look like? You were so busy overseeing the gold in your pocket, you forgot!', NULL),
  ('00000000-0000-4000-8000-000000001451', 'kanji', '除', '除', 31, 14, 'The buildings are at a surplus. Because of that, we will need to exclude some of them from our future plans. Also, we''ll need to remove some buildings too.', 'Working with you on this project to exclude buildings from the plan, as well as remove buildings that already exist is little Jo-Anne (じょ).', NULL),
  ('00000000-0000-4000-8000-000000001452', 'kanji', '尋', '尋', 31, 15, 'Wolverine is doing a construction job and he’s using his mouth to measure so he knows how many folks he needs to inquire about helping him with the job. Using one’s mouth is a strange way to measure something, but that’s just how Wolverine does things. Once he measures it all out, he’ll know how many construction workers he needs to inquire about working for him.', 'You decide to inquire as to why Wolverine is using his mouth to measure out this construction site. As you get closer you notice his cool ripped jeans (じん). Instead you inquire how he got such a fresh style. He looks you up and down, pulls out his claws, and tears yours up to match his. You’ve completely forgotten what it was you were asking, but who cares! Look how great you look!', NULL),
  ('00000000-0000-4000-8000-000000001453', 'kanji', '幾', '幾', 31, 16, 'You poop twice on a sleeping drunkard person and you find yourself wondering how many more times you can poop on them and wonder how much they can take before they realize what’s going on.', 'As you continue thinking about how much poop this drunkard can take and how many more poops you can drop on him, he begins to wake up. Quickly, you eke (いく) out one last poop before you scurry away. You eke that poop out just in time to make your escape.', NULL),
  ('00000000-0000-4000-8000-000000001454', 'kanji', '廊', '廊', 31, 17, 'The canopy guy is a guy who stands in the corridor trying to sell people canopies.', 'You take the corridor, but this time the canopy guy is gone. In his place is a new salesman. This one is trying to sell you roe (ろう).', NULL),
  ('00000000-0000-4000-8000-000000001455', 'kanji', '掃', '掃', 31, 18, 'Wolverine ties a towel around his forehead and takes out his fingers instead of his claws so he can sweep the floor clean. When Wolverine fights, his claws are out and he makes a big ol'' mess. But once the fighting is done, it''s time to get to work and sweep the mess up.', 'Wolverine knows that sweeping is good for the soul (そう). Plus, if you don''t help clean up after you defeat bad guys, you''re just as bad as them. Sweeping up the mess cleans your soul of any guilt too!', NULL),
  ('00000000-0000-4000-8000-000000001456', 'kanji', '泥', '泥', 31, 19, 'A tsunami came in and buried your flag so now you have to use a spoon and dig it out of the mud.', 'The time of day (でい) is high noon, so the sun soon dries the mud and makes it harder to dig through. It just might take you all day to spoon your way through this mud.', NULL),
  ('00000000-0000-4000-8000-000000001457', 'kanji', '棒', '棒', 31, 20, 'A tree in spring that''s nice and dry will make a good pole or rod. Break it out of the ground and it''s just flexible enough for tons of applications.', 'After much deliberation, you decide to use this pole to go bowling (ぼう). You line up a few more poles for the pins, and roll a rock toward them.', NULL),
  ('00000000-0000-4000-8000-000000001458', 'kanji', '驚', '驚', 31, 21, 'If you can write an interesting poem about winter while riding on a horse, I’ll be pretty surprised. It’s hard enough to write a poem as it is, let alone an interesting one. And then you’re riding on a horse and the poem has to be about winter? Heck, I’d be surprised if you didn’t fall off the horse and injure yourself.', 'You might also be surprised to learn that you are to ride this horse all across きょうと. That gives you a time limit. You have until you traverse きょうと to write this poem about winter.', NULL),
  ('00000000-0000-4000-8000-000000001459', 'kanji', '嘆', '嘆', 31, 22, 'You use your mouth when you see a Chinese person and you sigh. You sigh so loud that it’s practically a roar coming out of your mouth. Chinese people and Chinese things make you sigh because it reminds you of when you stayed in China and it brings up memories. The sigh is a sigh of nostalgia.', 'Your favorite Chinese thing to do is tan (たん). You can wander around without your shirt on and tan all day. No one will sigh or scoff at you, it’s perfectly acceptable. The Chinese just love to get their tan on.', NULL),
  ('00000000-0000-4000-8000-000000001460', 'kanji', '倉', '倉', 31, 23, 'The warehouse radical and the warehouse kanji are the same!', 'You have a warehouse to store all of your souls (そう). When people or animals you know pass away, you take their souls and store them in your dry warehouse for safekeeping. It''s a public service, really.', NULL),
  ('00000000-0000-4000-8000-000000001461', 'kanji', '孫', '孫', 31, 24, 'A child shares his lineage with a grandchild. The child passes his lineage down to his child and then that child’s child is the grandchild and between them all a lineage is shared.', 'The son (そん) of a son is a grandchild. In this case, a grandson. Easy.', NULL),
  ('00000000-0000-4000-8000-000000001462', 'kanji', '巣', '巣', 31, 25, 'Birds use grass and fruit to make their nests.', 'The bottom of the nest also seems to be padded with someone''s suit (す). Did... did this bird attack a human for this?!', NULL),
  ('00000000-0000-4000-8000-000000001463', 'kanji', '帯', '帯', 31, 26, 'There''s a mountain coming out of the ground that you want to climb, but your forehead needs a towel for all your sweat. You don''t have a towel, so you take off your belt and tie it around your forehead.', 'The belt isn''t absorbent enough, so you wrap it in your tie (たい) and then tie the whole thing around your forehead again.', NULL),
  ('00000000-0000-4000-8000-000000001464', 'kanji', '径', '径', 31, 27, 'You loiter around a tombstone to measure its diameter. You’re doing this to each tombstone, and if you loiter around long enough, you’ll soon know the diameter of every tombstone.', 'You need to know the diameter of each tombstone so you can make cakes (けい) for each one. But the cakes can''t be wider than the tombstones, or they''ll flop off onto the ground.', NULL),
  ('00000000-0000-4000-8000-000000001465', 'kanji', '救', '救', 31, 28, 'You request that winter rescue you from the warmth of the other seasons.', 'You get a note in the mail from winter! This is it, you''re going to be rescued! You open the note and it says, "I have rescued you with this cucumber (きゅう)." A cucumber falls out of the note.', NULL),
  ('00000000-0000-4000-8000-000000001466', 'kanji', '散', '散', 31, 29, 'If you play blackjack on the moon in the winter, your cards will scatter everywhere. The cards scatter because the gravity is so weak on the moon, so the blackjack game is prone to disaster.', 'You are playing blackjack with Santa-san (さん). Santa-san is doing his best to use his Christmas magic to prevent the scatter of cards, but it’s not working out so well. Good effort, Santa-san.', NULL),
  ('00000000-0000-4000-8000-000000001467', 'kanji', '粉', '粉', 31, 30, 'If you grind rice, every part of it, eventually it will become a fine powder. You can then use this rice powder as a part to create some other dish. Some kind of cake, perhaps.', 'Actually, grinding the rice down to a powder is super fun (ふん). It’s so fun you don’t want to stop! AH HAHAHAHA! RICE POWDER! SO FUN!', NULL),
  ('00000000-0000-4000-8000-000000001468', 'kanji', '脈', '脈', 31, 31, 'Under the moon while you sit on a cliff, you inject a syringe of tofu right into your vein. Ahh, tofu. You’re addicted to it. You sneak out to the cliff at night to get your tofu fix, injecting it straight into your vein.', 'Eventually, your friends and family find you at the cliff, tripping on tofu. Each and every vein on your body is engorged, pulsating with the effects of tofu. Your friends try and take you home. “You cyan’t myake (みゃく) me!” you slur, suffering from the effects of the tofu. “None of you cyan myake me go home! You cyan’t myake me! Nyah!”', NULL),
  ('00000000-0000-4000-8000-000000001469', 'kanji', '菜', '菜', 31, 32, 'You want some flowers so you take your cleat to the side of a tree hoping they''ll fall down, but you get a vegetable instead. What? You kick the tree again and another, different vegetable falls out.', 'You feed these vegetables (that you didn''t even want) to your cyborg (さい). It only needs a little though, since its stomach is so thin, so you just make it hold the rest.', NULL),
  ('00000000-0000-4000-8000-000000001470', 'kanji', '貨', '貨', 31, 33, 'You want to change your shellfish into freight so you can transport it. That means packing them up into giant freight containers.', 'To move this freight, you need a car (か). You strap all of the freight containers to the top of your car, stacked nice and high and precarious, so you can move it.', NULL),
  ('00000000-0000-4000-8000-000000001471', 'kanji', '陸', '陸', 31, 34, 'A building made from a womb must be placed upon the land.', 'The land around your womb building will, unfortunately, reek (りく) though.', NULL),
  ('00000000-0000-4000-8000-000000001472', 'kanji', '似', '似', 31, 35, 'A leader of (odd-looking) lions puts a drop of magic liquid on his face to look like a person resembles someone else. The leader of lions is going incognito, so he needs to resemble a person who is not himself. He takes this drop of powerful face paint and transforms.', 'Now he resembles an even greater leader, and all the lions get down on one knee (に) to pay their respects.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000001592', 'kanji', '剣', '剣', 35, 18, 'Tie a squid to a knife and you get a sword! Knives are too small to be considered a sword on their own. That''s why you strapped a squid to it. They''re the right shape, kinda pointed, so no one will know it''s just a knife.', 'You learned how to make swords this way from Ken (けん) the samurai. He put his own little squid buddy on his knife and now no one realizes it''s not a sword!', NULL),
  ('00000000-0000-4000-8000-000000001593', 'kanji', '寿', '寿', 35, 19, 'In spring, your measurements will reveal your lifespan. Only in spring can you measure your lifespan, just as easily as you measure your height and weight.', 'If your lifespan measurement isn''t as long as you''d like, you need to drink more small juice (じゅ) boxes this year. They''re good for your health, after all!', NULL),
  ('00000000-0000-4000-8000-000000001594', 'kanji', '彼', '彼', 35, 20, 'If you loiter around my skin, he will get angry at you. He is my boyfriend and he is very protective of me. So don’t loiter around my skin for too long or he will beat you up.', 'He says the only way he will stop beating you up is if you give him some curry (かれ). You give him some curry.', NULL),
  ('00000000-0000-4000-8000-000000001595', 'kanji', '恥', '恥', 35, 21, 'Your ear listens to your heart and feels shame. Your heart is full of shame for how you’ve lived your life and when your ear hears all the things you’ve done, your ear feels shame too.', 'You must cleanse your spirit of this shame. You decide to complete Haj (はじ). (Haj is the fifth pillar of Islam, and is a pilgrimage to Mecca during the month of Dhu al-Hijja). Upon arrival in Mecca, you think of a funny joke and bust out laughing. “HAHAHAHAHAHA!! (は) HAHAHAHAHA!!!” Oh man, you’re in a temple and that was completely inappropriate. You feel even more shame than before.', NULL),
  ('00000000-0000-4000-8000-000000001596', 'kanji', '杉', '杉', 35, 22, 'There’s a tree in your hair, I think it’s a cedar. How did that cedar tree get in your hair?
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000005414', 'vocabulary', '壊れる', '壊れる', 31, 55, '壊す adalah "merusak sesuatu". 壊れる adalah ketika sesuatu rusak atau rusak, dan Anda tidak melakukan kerusakan. Ini harus dipatahkan.', 'The reading comes from 壊す, so try not to break any of your memories and remember this.', NULL),
  ('00000000-0000-4000-8000-000000005415', 'vocabulary', '壊れ物', '壊れ物', 31, 56, 'Sesuatu yang mudah pecah, adalah sesuatu yang rapuh. Hati-hati dengan hal seperti ini.', 'The reading is 壊れる and 物 put together.', NULL),
  ('00000000-0000-4000-8000-000000005416', 'vocabulary', '既に', '既に', 31, 57, 'Maknanya salah satu sama dengan kanji sebelumnya, namun bisa juga berarti sudah.', 'The reading is different from what you learned with the kanji. But as I told you already, I''ll be there on Su-day (すで). It''s like Sunday, but not quite the same. Imagine your confusion when someone says this over and over, but you don''t know what Suday is.', NULL),
  ('00000000-0000-4000-8000-000000005417', 'vocabulary', '既存', '既存', 31, 58, 'Sesuatu yang dulunya ada, mungkin masih ada sekarang.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000005418', 'vocabulary', '既決', '既決', 31, 59, 'Sudah diputuskan sebelumnya, artinya sudah diputuskan dan diselesaikan.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000005419', 'vocabulary', '普通', '普通', 31, 60, 'Anda melewatinya seperti biasa. Kamu normal. Anda melakukan hal-hal secara normal, secara normal.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005420', 'vocabulary', '普段', '普段', 31, 61, 'Langkah-langkah normal adalah langkah-langkah yang benar-benar biasa. Itu adalah langkah-langkah yang biasa Anda lakukan, tidak seperti langkah-langkah aneh yang tidak biasa.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005421', 'vocabulary', '編む', '編む', 31, 62, 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya merajut jadi versi vocab verbanya adalah merajut.', 'When you start to knit, you always end up with the same thing every time when you''re done, no matter what you''re trying to make: The letter "A" (あ). It''s so frustrating that you can''t knit anything else.', NULL),
  ('00000000-0000-4000-8000-000000005422', 'vocabulary', '編集', '編集', 31, 63, 'Rajut dan kumpulkan kembali semuanya, yang Anda rajut. Saat Anda melakukan ini untuk memperbaiki keadaan dan menyatukannya kembali, ini adalah pengeditan.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000005423', 'vocabulary', '編者', '編者', 31, 64, 'Seseorang yang merajut adalah orang yang menyatukan kata-kata dan menjadikannya lebih baik. Seseorang ini adalah seorang editor.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000005424', 'vocabulary', '外務大臣', '外務大臣', 31, 65, 'Menteri tugas luar negeri (大臣) adalah seseorang yang bertugas menangani hal-hal yang berada di luar negeri. Ini adalah menteri luar negeri.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005425', 'vocabulary', '総理大臣', '総理大臣', 31, 66, 'Menteri "perdana menteri" (総理) adalah kata lengkap untuk perdana menteri.', 'This is a jukugo word that uses the on''yomi readings of the kanji. You should be able to read this on your own. It''s also a combination of the words 総理 and 大臣 from previous levels.', NULL),
  ('00000000-0000-4000-8000-000000005426', 'vocabulary', '華やか', '華やか', 31, 67, 'Sesuatu yang mencolok adalah sesuatu yang mencolok.', 'For the reading, think about something that''s showy... in particular, 花s (はな). Flowers are super showy, always showing off their colors and stuff.', NULL),
  ('00000000-0000-4000-8000-000000005427', 'vocabulary', '中華', '中華', 31, 68, '中国 adalah Tiongkok, kan? Itulah yang diwakili oleh 中 ini. Dan tentu saja orang Cina terkenal super mencolok, itulah sebabnya Anda harus suka pamer di sana.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000005428', 'vocabulary', '地下街', '地下街', 31, 69, 'Jalan bawah tanah (地下) tidaklah se-jalan bawah tanah seperti yang terlihat. Namun, banyak jalan dan area bawah tanah di Jepang yang cenderung menjadi pusat perbelanjaan bawah tanah. Itu atau kereta bawah tanah/kereta api, tapi pusat perbelanjaan bawah tanah jauh lebih menarik.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000005429', 'vocabulary', '豪華', '豪華', 31, 70, 'Oh wow, itu luar biasa mencolok! Apapun benda itu, mewah dan indah dan aku menginginkannya.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005432', 'vocabulary', '鑑定', '鑑定', 31, 71, 'Ketika seseorang menentukan sesuatu, mungkin tidak apa-apa. Namun, ketika penentu model menentukan sesuatu, itulah penentuan terbaik yang pernah ada. Itulah penilaian seseorang yang mempunyai pendapat ahli.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000005433', 'vocabulary', '除く', '除く', 31, 72, 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mengecualikan jadi versi vocab verbanya adalah mengecualikan.', 'You would like to exclude your nose (のぞ) because you don''t like your nose. Imagine your strong feelings about your nose as you decide to exclude it.', NULL),
  ('00000000-0000-4000-8000-000000005434', 'vocabulary', '掃除', '掃除', 31, 73, 'Tolong sapu dan singkirkan semua kotoran dari lantai. Jika Anda sering melakukan ini, hal itu menjadi pembersihan.', 'This is a jukugo word, which usually means on''yomi readings from the kanji. For this one though, you have to remember to read the 除 part as じ. Just keep in mind that cleaning (cleanliness) is next to godliness and so is Jesus (じ). So, Jesus is like cleaning. Easy.', NULL),
  ('00000000-0000-4000-8000-000000005435', 'vocabulary', '除外', '除外', 31, 74, 'Kecualikan yang ini dan letakkan di luar apa yang sedang kita pertimbangkan. Ini adalah pengecualian.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000005436', 'vocabulary', '尋ねる', '尋ねる', 31, 75, 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bertanya, jadi versi vocab verbanya adalah bertanya.', 'I''d like to inquire about a few things. Wait, what? You won''t cooperate? How about I just taze (たず) you with this tazer then? BzzzbbzbhhhAHHHHHH!', NULL),
  ('00000000-0000-4000-8000-000000005437', 'vocabulary', '尋問', '尋問', 31, 76, 'Ketika Anda bertanya tentang suatu masalah, Anda cenderung bertanya tentang masalah tersebut. Mengapa seperti ini? Apa yang telah terjadi? Apakah lebih besar dari kotak roti?', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005438', 'vocabulary', '幾ら', '幾ら', 31, 77, 'Ini memiliki arti yang sama dengan kanji, yaitu seberapa besar artinya. Untuk mengingat hal ini, coba pikirkan bagaimana Ra, Dewa Mesir, selalu bertanya, "Berapa biaya untuk membangun piramida ini?" Ugh, terlalu banyak, ayo kita pekerjakan beberapa budak.', 'Karena kata ini terdiri dari kanji yang ditempelkan hiragana, bisa dipastikan kata tersebut akan menggunakan bacaan kun''yomi. Anda sudah mempelajari bacaan ini jadi Anda harus bisa membacanya!', NULL),
  ('00000000-0000-4000-8000-000000005439', 'vocabulary', '幾つ', '幾つ', 31, 78, 'Ini memiliki arti yang sama dengan kanji, yaitu berapa banyak artinya. Anda mengetahui hal ini karena Anda bertanya "berapa banyak" dan mereka menjawab "つ." Ini juga bisa digunakan untuk menanyakan berapa umur seseorang, namun umumnya hanya untuk usia anak-anak.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000005621', 'vocabulary', '雑誌', '雑誌', 33, 50, 'Majalah acak hampir semuanya majalah. Hanya sekumpulan barang acak di dalamnya, menjadikannya sebuah majalah.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005622', 'vocabulary', '窓口', '窓口', 33, 51, 'Mulut jendela adalah tempat Anda pergi untuk membeli tiket di luar jendela. Anda tahu bagaimana ada jendela-jendela yang berlubang, atau jendela itu sendiri yang berlubang? Itulah jenis jendela tiket yang saya bicarakan.', 'The reading is the readings for 窓 and the reading for 口.', NULL),
  ('00000000-0000-4000-8000-000000005623', 'vocabulary', '窓', '窓', 33, 52, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'The reading is the same as the kanji reading you learned.', NULL),
  ('00000000-0000-4000-8000-000000005624', 'vocabulary', '否', '否', 33, 53, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Since this word is made up of a single kanji, it probably uses the kun''yomi reading. You did not learn this reading, so here''s a mnemonic to help you: 
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000005835', 'vocabulary', '時刻表', '時刻表', 34, 150, 'Sesuatu yang mengukir waktu untuk sesuatu (katakanlah, pada sebuah tanda besar) dan kemudian mengungkapkannya kepada dunia, adalah jadwal atau jadwal.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005836', 'vocabulary', '深刻', '深刻', 34, 151, 'Ukiran yang dalam sangatlah serius dan serius. Bayangkan saja ditebas dengan pedang. Jika ukirannya dalam, itu serius.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005837', 'vocabulary', '閉じる', '閉じる', 35, 37, 'Cara lain untuk mengatakan menutup atau menutup. Versi kata kerja dari kanji 閉.', 'The reading is different from, say, 閉める or しまる. Instead, the reading is とじる. Why? Because you shut your toe (と) in the door because it sheared off the hinges and was out of control.', NULL),
  ('00000000-0000-4000-8000-000000005838', 'vocabulary', '一筋', '一筋', 35, 38, 'Anda mempunyai satu otot, oleh karena itu ia hanya melakukan satu hal. Itu saja. Ia melakukan satu hal dengan sepenuh hati. Yaitu dengan sungguh-sungguh dan sungguh-sungguh melakukan satu hal itu.', 'The reading is a bit weird. It''s the kun''yomi readings, where 一 is ひと and 筋 is すじ. Look back on the vocab words that use these readings to remember this one.', NULL),
  ('00000000-0000-4000-8000-000000005839', 'vocabulary', '垂れる', '垂れる', 35, 39, 'Jika 垂らす berarti "menggantung sesuatu" maka ini berarti menjuntai atau menetes. Kamu tidak melakukan penggantungan, yang jarang terjadi (れる), karena biasanya kamulah yang melakukan penggantungan.', 'The reading is the same as 垂らす.', NULL),
  ('00000000-0000-4000-8000-000000005840', 'vocabulary', '宣言する', '宣言する', 35, 40, 'Jika 宣言 adalah "proklamasi", maka versi kata kerjanya adalah memberitakan.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005841', 'vocabulary', '盛り上げる', '盛り上げる', 35, 41, '盛る adalah "menumpuk". Jika Anda "menaikkan" (上げる) apa yang Anda timbun, itu berarti menimbun sesuatu, menjadikan kata ini menumpuk atau menumpuk. Kata ini juga digunakan ketika ingin menghidupkan suatu hal. Kumpulkan energi itu dan gejolak segalanya!', 'The reading comes from 盛る and 上げる. Know those words and you''ll be able to read this one too.', NULL),
  ('00000000-0000-4000-8000-000000005842', 'vocabulary', '裏切り者', '裏切り者', 35, 42, 'Seseorang yang menusuk dari belakang (裏切り) seseorang adalah pengkhianat.', 'The reading is 裏切り and an exception reading for 者. Just think about how you''d think of a traitor as a "thing" (物) and not a person.', NULL),
  ('00000000-0000-4000-8000-000000005843', 'vocabulary', '諸々', '諸々', 35, 43, 'Anda memiliki berbagai hal yang berbeda. Mereka bermacam-macam. Anda memiliki semua jenisnya.', 'The reading is a bit weird. Just think about how when you have various things, you probably have a lot of things. What do you want? You want more (もろ) of those things. More more more!', NULL),
  ('00000000-0000-4000-8000-000000005844', 'vocabulary', '三つ編み', '三つ編み', 35, 44, '編む berarti "merajut". Saat Anda merajut bertiga, Anda merajut dengan gaya kepang. Apa yang kamu kepang? Rambut. Itu membuat rambut dikepang ini.', 'The reading is the み from 三つ and つ and 編む combined into one (or should I say three?) braids. Just watch out because this isn''t みっつあみ, it''s just みつあみ. Listen to the audio a few times to make sure you remember how it''s spelled and pronounced!', NULL),
  ('00000000-0000-4000-8000-000000005845', 'vocabulary', '閉まる', '閉まる', 35, 45, 'Jika 閉める adalah "menutup" atau "menutup" ini akan menjadi versi di mana Anda tidak melakukan apa pun dan sesuatu akan menutup dengan sendirinya. Kata ini adalah ditutup atau ditutup. Kamu mengetahui hal ini karena kamu meletakkan tanganmu di pintu untuk membukanya, tapi kemudian pintu itu menutup (dengan sendirinya) di tanganmu, merusak (まる) tanganmu selamanya.', 'The reading is the same as 閉める.', NULL),
  ('00000000-0000-4000-8000-000000005847', 'vocabulary', '納まる', '納まる', 35, 46, 'Jika 納める berarti "menyediakan" atau "menyampaikan", maka kata ini berarti sesuatu telah diserahkan: jadi harus dipenuhi atau diselesaikan. Anda tidak melakukan penyediaan, dan Anda mengetahui hal ini karena jika Anda ketahuan memasok, reputasi Anda akan rusak (まる seumur hidup).', 'The reading is the same as 納める.', NULL),
  ('00000000-0000-4000-8000-000000005848', 'vocabulary', '納得', '納得', 35, 47, 'Saya akan menyediakan dan Anda akan memperolehnya. Apakah itu terdengar bagus? Apakah saya mendapat persetujuan Anda? Saya dapat melihat bahwa Anda memahami dan yakin. Anda berencana menerima lamaran saya, bukan?', 'The reading is a bit weird for 納. Just imagine asking the consent question from the meaning, then have the other person say "Nahh! (なっ), no consent!"', NULL),
  ('00000000-0000-4000-8000-000000005849', 'vocabulary', '否定形', '否定形', 35, 48, '否定 adalah penolakan. Ingat bagaimana 形 terkadang mengacu pada tata bahasa tense/tipe? Nah, dengan tata bahasa tipe penolakan, Anda memiliki bentuk negatif, menjadikannya kalimat negatif.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005850', 'vocabulary', '否定する', '否定する', 35, 49, 'Jika 否定 adalah "penyangkalan", maka versi kata kerjanya adalah menyangkal.', 'This is a jukugo word that uses the on''yomi readings of the kanji. You should be able to read this on your own. Will help to know the word 否定 as well.', NULL),
  ('00000000-0000-4000-8000-000000005851', 'vocabulary', '尊敬する', '尊敬する', 35, 50, 'Jika 尊敬 adalah "menghormati" maka versi kata kerjanya adalah menghormati.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005852', 'vocabulary', '尊敬語', '尊敬語', 35, 51, '尊敬 adalah rasa hormat. Bahasa penghormatan adalah bahasa Jepang kehormatan (atau bahasa kehormatan, meskipun biasanya ini mengacu pada bahasa Jepang).', 'The reading is 尊敬 plus 語 put together.', NULL),
  ('00000000-0000-4000-8000-000000005853', 'vocabulary', '暮らし', '暮らし', 35, 52, 'Jika 暮らす berarti "hidup" atau "menjalani hidup" maka versi kata bendanya adalah hidup.', 'The reading is the same as 暮らす.', NULL),
  ('00000000-0000-4000-8000-000000005854', 'vocabulary', '同音異義語', '同音異義語', 35, 53, 'Anda memiliki bunyi yang sama dengan arti yang berbeda (異義), dan itu adalah bagian dari bahasa. Kedengarannya sama... artinya berbeda... yang terdengar seperti homofon, atau homonim.', 'This is a jukugo word that uses the on''yomi readings of the kanji. You should be able to read this on your own. All I know is there''s probably not a homonym for this word, for it is huge.', NULL),
  ('00000000-0000-4000-8000-000000005855', 'vocabulary', '著作権', '著作権', 35, 54, '著作 adalah "menulis" atau "penulis". Hak yang dimiliki oleh sebuah tulisan disebut dengan hak cipta.', 'This is a jukugo word that uses the on''yomi readings of the kanji. You should be able to read this on your own. Will help to know 著作 first, too.', NULL),
  ('00000000-0000-4000-8000-000000005856', 'vocabulary', '蒸し暑い', '蒸し暑い', 35, 55, '蒸れる berarti "menjadi lembab." Jadi, kalau cuacanya panas lembab, berarti cuacanya panas dan lembap (atau bisa dibilang lembab, karena biasanya berarti panas juga). Ini adalah kata yang berguna untuk musim panas di Jepang, karena Anda akan selalu mengeluh tentang hal ini.', 'The reading comes from 蒸れる and 暑い. Know those and you know this too.', NULL),
  ('00000000-0000-4000-8000-000000005857', 'vocabulary', '蒸し返す', '蒸し返す', 35, 56, 'Anda mengukus sesuatu untuk mengembalikannya ke kondisi hangat sebelumnya. Ini adalah saat Anda ingin memanaskan kembali sesuatu. Namun kita biasanya menggunakannya untuk membicarakan sesuatu yang berulang kali dibicarakan atau diargumentasikan. Makanya maksudnya rehash atau mengungkit lagi. Anda mengungkit kenangan dari masa lalu dan menghidupkannya kembali.', 'The reading comes from 蒸れる and 返す. Combine this knowledge to reheat your memories.', NULL),
  ('00000000-0000-4000-8000-000000005858', 'vocabulary', '装う', '装う', 35, 57, 'Jika Anda berpakaian sendiri, Anda menutupi siapa diri Anda dan mencoba menjadi orang lain. Anda mencoba berpura-pura. Anda mencoba untuk berbohong. Anda mencoba berpura-pura.', 'While you go to feign that you''re someone or something else, someone calls you out on it: "you so (よそお) much a liar!"', NULL),
  ('00000000-0000-4000-8000-000000005859', 'vocabulary', '遅れる', '遅れる', 35, 58, 'Jika sesuatu atau seseorang lambat, dan mereka "melakukannya lambat" maka mereka akan terlambat.', 'What is slow and probably going to be late all the time? A big oak (おく). Oaks have trouble moving, and are slow, and therefore are always late, too.', NULL),
  ('00000000-0000-4000-8000-000000005860', 'vocabulary', '遅刻', '遅刻', 35, 59, 'Pengukiran yang lambat sangatlah lambat. Jika Anda mengukir sesuatu dengan lambat, itu akan memakan waktu lama. Anda akan terlambat dengan ukiran lambat seperti itu.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005861', 'vocabulary', '遅延', '遅延', 35, 60, 'Saya terlalu lambat, jadi kami harus memperpanjang waktu peluncuran produk ini. Ini penundaan :(', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005862', 'vocabulary', '彫刻', '彫刻', 35, 61, 'Anda mengukir lalu Anda mengukir lagi. Banyak sekali ukirannya sampai, tunggu, wow, sepertinya ada sesuatu! Semua ukiran itu menjadi patung!', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005863', 'vocabulary', '測る', '測る', 35, 62, 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya mengukur jadi kata kerja vocab artinya mengukur. Kata ini umumnya berkaitan dengan pengukuran ilmiah atau medis.', 'Remember another word that means "to measure?" It is 量る, and has the same reading as this word. That should make things easier to remember.', NULL),
  ('00000000-0000-4000-8000-000000005864', 'vocabulary', '推測', '推測', 35, 63, 'Anda dapat menyimpulkan dan mengukur semua yang Anda inginkan. Jika Anda melakukan cukup banyak hal, Anda akan mendapatkan dugaan dan spekulasi bagus dari kesimpulan dan pengukuran tersebut.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005865', 'vocabulary', '予測', '予測', 35, 64, 'Ukuran sebelumnya adalah ketika Anda membuat prediksi terhadap sesuatu.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005866', 'vocabulary', '観測', '観測', 35, 65, 'Lihat dan ukur apa yang Anda tonton. Ini adalah observasi. Ini bukan sekedar menonton, ini lebih dari itu.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005867', 'vocabulary', '破る', '破る', 35, 66, 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya merobek, jadi versi verbanya adalah merobek.', 'You start to tear the cloth. You don''t know if you''re supposed to or not. The crowd isn''t sure either. You hear kind of a yah boo (やぶ) reaction going on, making you unsure if you should continue or stop. Yah! Boo. Yah! Boo!', NULL),
  ('00000000-0000-4000-8000-000000005868', 'vocabulary', '破壊', '破壊', 35, 67, 'Robek dan hancurkan semuanya, hancurkan semuanya. Pengrusakan! Pembongkaran!', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005869', 'vocabulary', '破船', '破船', 35, 68, 'Robekan pada kapal Anda akan menyebabkannya karam, menjadikannya kapal karam.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005870', 'vocabulary', '破産', '破産', 35, 69, 'Jika seseorang merampas seluruh properti Anda, hal itu akan menyebabkan kebangkrutan. Dengan semua harta benda Anda terkoyak, Anda akan bangkrut. Orang jahat apa yang melakukan itu?', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005871', 'vocabulary', '田舎', '田舎', 35, 70, 'Sebuah sawah dan sebuah pondok. Inilah gambaran pedesaan bagi saya. Ini pedesaan. Cuma cottage dan sawah...', 'The reading doesn''t really make sense for the kanji, and is an exception for sure. Just think about how when you''re in the countryside you''re in 中 (いなか) of nowhere.', NULL),
  ('00000000-0000-4000-8000-000000005872', 'vocabulary', '兵舎', '兵舎', 35, 71, 'Pondok tentara adalah tempat tinggal para prajurit. Ini adalah barak.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005873', 'vocabulary', '庁舎', '庁舎', 35, 72, 'Pondok kantor pemerintahan adalah tempat penyimpanan kantor pemerintahan. Itu gedung kantor pemerintah.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005874', 'vocabulary', '講演', '講演', 35, 73, 'Lakukan ceramah Anda. Ini adalah kuliahmu. Ini adalah alamat Anda kepada orang-orang.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005875', 'vocabulary', '講師', '講師', 35, 74, 'Pakar perkuliahan adalah dosen atau instruktur.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005876', 'vocabulary', '講義', '講義', 35, 75, 'Ceramah kebenaran tetaplah ceramah.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005877', 'vocabulary', '滞る', '滞る', 35, 76, 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti stagnan, dan versi kosakata kata kerjanya terlambat. Toh, kalau ada yang mandek, tidak maju, jadi tertunda.', 'Your work tends to be overdue, so you get a lot of to-do calls (とどこおる) from your boss, reminding you to do your work. These calls are pretty annoying, but at least your work is less delayed.', NULL),
  ('00000000-0000-4000-8000-000000005878', 'vocabulary', '遅滞', '遅滞', 35, 77, 'Saya terlalu lambat sehingga segalanya mulai mandek. Benar-benar penundaan.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005879', 'vocabulary', '紹介', '紹介', 35, 78, 'Perkenalan saya dimasukkan ke sana agar Anda dapat mendengarnya. Demikianlah perkenalan saya. Masukkan itu.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005880', 'vocabulary', '介入', '介入', 35, 79, 'Saya terjebak dalam diri saya sendiri dan memasuki kehidupan pribadi Anda. Karena aku peduli, kamu tahu? Saya tidak ingin Anda kecanduan My Little Pony lagi, jadi ini adalah intervensi.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005881', 'vocabulary', '己', '己', 35, 80, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Itu juga berarti diriku dan aku.', 'As for myself? I''m not Bob. oh no, Ray (おのれ), Ray is my name.', NULL),
  ('00000000-0000-4000-8000-000000005882', 'vocabulary', '自己', '自己', 35, 81, 'Diri Anda sendiri, adalah diri Anda sendiri atau diri Anda sendiri.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005883', 'vocabulary', '厄介', '厄介', 35, 82, 'Yang kurang beruntung justru terjebak di sana. Banyaknya ketidakberuntungan berujung pada masa-masa yang sangat menyusahkan dan memberatkan.', 'This is a jukugo word that uses the on''yomi readings of the kanji. You should be able to read this on your own. The やく gets changed to やっ.', NULL),
  ('00000000-0000-4000-8000-000000005884', 'vocabulary', '亀', '亀', 35, 83, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. TERBAKAR, TERBAKAR, TERBAKAR.', 'The reading is the same as what you learned with the kanji.', NULL),
  ('00000000-0000-4000-8000-000000005885', 'vocabulary', '海亀', '海亀', 35, 84, 'Penyu adalah penyu. Cowabunga!', 'The reading is the kun''yomi readings of these kanji, put together. I suppose it''s because it''s like two separate words put together into one. That makes this word read as うみがめ, where the かめ gets rendaku''d.', NULL),
  ('00000000-0000-4000-8000-000000005886', 'vocabulary', '互い', '互い', 35, 85, 'Meskipun terlihat seperti kata sifat, ini adalah versi kata benda dari kanji, sehingga saling menguntungkan. Itu juga berarti satu sama lain dan timbal balik dan bersama-sama juga.', 'Let''s help each other. Maybe if we work together we can get rid of this tagger (たが) tagging graffiti all over our neighborhood.', NULL),
  ('00000000-0000-4000-8000-000000005887', 'vocabulary', '相互', '相互', 35, 86, 'Saling menguntungkan dan saling menguntungkan.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005888', 'vocabulary', '交互', '交互', 35, 87, 'Anda bercampur, lalu Anda saling bergaul, lalu Anda bercampur, dan kemudian Anda menjadi saling menguntungkan. Sebagai alternatif, Anda dapat mencampurnya lagi?', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005889', 'vocabulary', '真剣', '真剣', 35, 88, 'Kenyataan dari pedang ini adalah bahwa pedang itu akan membelahmu menjadi dua dan membunuhmu dengan mudah. Fakta bahwa hal ini benar adalah hal yang sangat serius. Sangat serius.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005890', 'vocabulary', '剣道', '剣道', 35, 89, 'Jalur pedang dikenal dengan nama kendo. Bisa juga dikatakan anggar Jepang.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005891', 'vocabulary', '寿司', '寿司', 35, 90, 'This is ateji, meaning the meanings of the kanji don''t mean anything, only the sounds are being borrowed to make the word in Japanese. So, skip to the reading and use that to remember the meaning. It''s an English word too now, after all.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005892', 'vocabulary', '寿命', '寿命', 35, 91, 'Your lifespan is your fate and will show you how long your lifespan is.', 'You did learn the reading of 寿, but the reading for 命 is an exception. When you think of a lifespan, think of how that affects everyone. Me, you... well, just those things. Combine them both into myou (みょう). That is who the lifespan affects. Myou!', NULL),
  ('00000000-0000-4000-8000-000000005893', 'vocabulary', '長寿', '長寿', 35, 92, 'A long lifespan is a long life.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005894', 'vocabulary', '喜寿', '喜寿', 35, 93, 'You can rejoice because your lifespan has reached this special point. That special point is your seventy seventh birthday. So many sevens, lucky!', 'The readings are the on''yomi reading. You''ve seen the on''yomi reading of 喜 before, though it may be hard to remember at this point. Maybe you can think about how when you reach this seventy seventh birthday, all you want is a key (き) to the city so you can do whatever you want.', NULL),
  ('00000000-0000-4000-8000-000000005895', 'vocabulary', '福寿', '福寿', 35, 94, 'Luck for your whole lifespan, that''s a life of happiness and longevity.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005896', 'vocabulary', '彼', '彼', 35, 95, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Bacaannya sama dengan yang Anda pelajari dengan kanji.', NULL),
  ('00000000-0000-4000-8000-000000005897', 'vocabulary', '彼氏', '彼氏', 35, 96, 'A he mister bukan hanya dia, tapi "mister he", dan mister dia adalah dia, pacarmu.', 'The readings are the ones you learned with the kanji.', NULL),
  ('00000000-0000-4000-8000-000000005898', 'vocabulary', '彼ら', '彼ら', 35, 97, 'Ini dia tapi jamak. Kata "ra" menjadikannya jamak, menjadikannya "mereka" atau "mereka". Meskipun gen ini biasanya merujuk pada sekelompok pria, namun bisa juga mencakup wanita.', 'Bacaannya sama dengan yang Anda pelajari dengan kanji.', NULL),
  ('00000000-0000-4000-8000-000000005899', 'vocabulary', '恥ずかしい', '恥ずかしい', 35, 98, 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari rasa malu? Ini mungkin memalukan atau bahkan memalukan.', 'When you''re ashamed it''s even worse when someone laughs at you: ha (は) ha ha!"', NULL),
  ('00000000-0000-4000-8000-000000005900', 'vocabulary', '恥', '恥', 35, 99, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'This is also the reading you learned. How nice! But if you don''t remember it, what a shame. What an embarrassment this must be for you.', NULL),
  ('00000000-0000-4000-8000-000000005901', 'vocabulary', '杉', '杉', 35, 100, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'The reading is the same as the one you learned with the kanji. This will be particularly useful for names, as there''s a lot of names with 杉.', NULL),
  ('00000000-0000-4000-8000-000000005902', 'vocabulary', '果汁', '果汁', 35, 101, 'Sup buah sebenarnya bukan sup, melainkan jus buah.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000005903', 'vocabulary', '汁', '汁', 35, 102, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Since this word is made up of a single kanji, it probably uses the kun''yomi reading. You did not learn this reading, so here''s a mnemonic to help you: 
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000006039', 'vocabulary', '遅い', '遅い', 37, 49, 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat lambat? Lambat (atau, jika lambat, mungkin Anda juga terlambat).', 'How slow are you? You are oh so slow (おそ).', NULL),
  ('00000000-0000-4000-8000-000000006040', 'vocabulary', '恥ずかしがる', '恥ずかしがる', 37, 50, '恥ずかしい adalah "memalukan." Ini adalah versi kata kerja. Apa jadinya jika seseorang merasa malu? Mereka menjadi pemalu dan pemalu. Itu sebabnya kata ini berarti malu atau malu.', 'The reading comes from 恥ずかしい.', NULL),
  ('00000000-0000-4000-8000-000000006041', 'vocabulary', '破れる', '破れる', 37, 51, 'Jika 破る berarti "merobek" atau "merobek", maka ini berarti robek atau patah atau terkoyak.', 'The reading comes from 破る.', NULL),
  ('00000000-0000-4000-8000-000000006042', 'vocabulary', '自己紹介', '自己紹介', 37, 52, 'Pengenalan diri (自己) (紹介) adalah pengenalan diri.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006043', 'vocabulary', '紹介する', '紹介する', 37, 53, '紹介 adalah perkenalan. Jadi versi kata kerjanya adalah memperkenalkan.', 'This is a jukugo word that uses the on''yomi readings of the kanji. You should be able to read this on your own. Helps that I introduced introduction to you earlier.', NULL),
  ('00000000-0000-4000-8000-000000006044', 'vocabulary', '紹介状', '紹介状', 37, 54, 'Ingat bagaimana 年賀状 merupakan kartu tahun baru? Ini jenis kartu/surat lain, tapi kali ini untuk perkenalan (紹介), jadi surat perkenalan.', 'This is a jukugo word that uses the on''yomi readings of the kanji. You should be able to read this on your own. Will help to know 紹介 as well.', NULL),
  ('00000000-0000-4000-8000-000000006045', 'vocabulary', '汁物', '汁物', 37, 55, 'Benda sup adalah apa yang Anda gunakan untuk menyebut sup.', 'The reading is both the kun''yomi readings combined to form one word. So, you''ll want to make sure you know the word 汁.', NULL),
  ('00000000-0000-4000-8000-000000006046', 'vocabulary', '味噌汁', '味噌汁', 37, 56, 'You know that 味噌 is "miso," and that 汁 is "soup." So, combine them together and you have Miso Soup.', 'The reading is 味噌 plus the vocab 汁 put together.', NULL),
  ('00000000-0000-4000-8000-000000006047', 'vocabulary', '酔っ払い', '酔っ払い', 37, 57, 'Saatnya membayar atas mabukmu. Anda mencobanya, tetapi Anda tidak dapat membayar atas mabuknya. Anda pasti sangat mabuk untuk memikirkan hal itu.', 'This is a combination of 酔う and 払い, put together with some small っ and a rendaku added in because you''re drunk.', NULL),
  ('00000000-0000-4000-8000-000000006048', 'vocabulary', '二日酔い', '二日酔い', 37, 58, 'Di hari kedua, Anda mengalami mabuk dengan cara yang berbeda... dalam bentuk mabuk.', 'The reading is 二日 and 酔い put together (the reading for that comes from 酔う).', NULL),
  ('00000000-0000-4000-8000-000000006049', 'vocabulary', '給油所', '給油所', 37, 59, 'Tempat pengisian bahan bakar (給油) adalah tempat di mana Anda mengisi bahan bakar. Ini bisa berupa pompa bensin atau pompa bensin.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006050', 'vocabulary', '跳ぶ', '跳ぶ', 37, 60, 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti melompat dan versi vocab verbanya adalah melompat atau melompat atau melompat. Pada dasarnya segala sesuatu yang mengangkat kedua kaki dari tanah melalui penggerak kaki Anda sendiri.', 'Know how 飛ぶ means "to fly"? This is a similar idea, though this time you''re not flying nearly as much, because you''re just hopping or jumping. Anyways, the readings are the same.', NULL),
  ('00000000-0000-4000-8000-000000006051', 'vocabulary', '昭和', '昭和', 37, 61, 'Masa damai yang bersinar adalah masa yang dikenal sebagai Era Showa. Ini juga bisa merujuk pada Kaisar Showa atau hanya Showa itu sendiri. Semuanya Showa ada di sini.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006052', 'vocabulary', '漁師', '漁師', 37, 62, 'Seorang ahli memancing adalah seorang nelayan.', 'This is a jukugo word that uses the on''yomi readings of the kanji. You should be able to read this on your own. The reading is the りょう reading, because you gotta get in your row boat to be a fisherman.', NULL),
  ('00000000-0000-4000-8000-000000006053', 'vocabulary', '漁船', '漁船', 37, 63, 'Perahu nelayan adalah perahu nelayan.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006054', 'vocabulary', '漁業', '漁業', 37, 64, 'Industri perikanan adalah industri perikanan atau perikanan.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006055', 'vocabulary', '償う', '償う', 37, 65, 'Melakukan reparasi berarti memberi kompensasi atau menebus sesuatu. Anda akan menebus dosa-dosa Anda.', 'When you try to compensate for everything you''ve ever done wrong, you become too good for your own britches. You are too good now (つぐなう).', NULL),
  ('00000000-0000-4000-8000-000000006056', 'vocabulary', '弁償', '弁償', 37, 66, 'Dialek saya telah menyinggung Anda? Saya akan melakukan perbaikan dengan memberi Anda penggantian dan sejumlah kompensasi. Maaf dialek saya sangat buruk sehingga Anda tidak dapat memahami ucapannya. Ini uangmu kembali.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006057', 'vocabulary', '刑務所', '刑務所', 37, 67, 'Tempat tugas hukuman adalah tempat Anda pergi untuk melakukan tugas hukuman Anda. Itu adalah penjara atau penjara.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006058', 'vocabulary', '死刑', '死刑', 37, 68, 'Hukuman mati adalah hukuman mati.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006059', 'vocabulary', '刑事', '刑事', 37, 69, 'Tindakan menghukum adalah ketika seseorang keluar untuk mencari orang yang berbuat jahat, agar dapat dihukum. Orang yang melakukan ini adalah orang-orang seperti detektif polisi (atau detektif).', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006060', 'vocabulary', '刑期', '刑期', 37, 70, 'Masa hukuman adalah masa di mana Anda dihukum di penjara. Ini adalah hukuman penjara Anda.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006061', 'vocabulary', '刑罰', '刑罰', 37, 71, 'Hukuman hukuman adalah hukuman.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006062', 'vocabulary', '終身刑', '終身刑', 37, 72, 'Sampai akhir seseorang, Anda akan dihukum. Jika Anda dihukum sampai akhir, Anda diberi hukuman seumur hidup.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006063', 'vocabulary', '募る', '募る', 37, 73, 'Kanjinya adalah merekrut sehingga versi kosakata kata kerjanya, menurut Anda, adalah ''merekrut'', tetapi itu untuk memohon sesuatu atau mengundang sesuatu atau untuk mengangkat sesuatu. Jadi, ini seperti merekrut, namun alih-alih merekrut orang, Anda merekrut berdasarkan sesuatu dan tindakan.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000006241', 'vocabulary', '跳ねる', '跳ねる', 39, 43, 'Jangan bingung dengan 跳ぶ, kata ini memiliki arti yang sama. Namun bacaannya berbeda.', 'The reading for this one is は because you''re laughing (HAHAHA!!) at the person who put Nair (ねる) on their legs, then only finding it to be really painful, so they have to jump around to get the pain to go away.', NULL),
  ('00000000-0000-4000-8000-000000006242', 'vocabulary', '縄跳び', '縄跳び', 39, 44, 'Tali yang Anda lompati adalah lompat tali.', 'The reading is the vocab words 縄 and 跳ぶ, put together.', NULL),
  ('00000000-0000-4000-8000-000000006243', 'vocabulary', '応募する', '応募する', 39, 45, 'Jika 応募 adalah "lamaran" maka versi kata kerjanya adalah melamar atau mendaftar.', 'The reading is the same as 応募''s reading, though knowing the readings of the kanji will take care of things too.', NULL),
  ('00000000-0000-4000-8000-000000006244', 'vocabulary', '本塁打', '本塁打', 39, 46, 'Pukulan yang Anda dapatkan dalam bisbol yang membawa Anda ke pelat asal adalah home run. HOOOMMEERUNNNNN!', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006245', 'vocabulary', '崩れる', '崩れる', 39, 47, 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya hancur dan versi vocab verbanya artinya hancur, seperti ada sesuatu yang runtuh atau runtuh.', 'The reading comes from 崩す, so if you know that you know this reading as well!', NULL),
  ('00000000-0000-4000-8000-000000006246', 'vocabulary', '払い戻す', '払い戻す', 39, 48, '払い berarti "pembayaran" dan 戻す berarti "mengembalikan". Jika Anda mengembalikan pembayaran, Anda akan membayar kembali, mengembalikan dana, atau mengganti biaya seseorang atas pembayarannya.', 'The readings come from 払い and 戻す.', NULL),
  ('00000000-0000-4000-8000-000000006247', 'vocabulary', '弾く', '弾く', 39, 49, 'Anda akan berpikir bahwa ini berarti "menembak" tetapi sebenarnya tidak. Artinya memainkan alat musik petik. Ini sebenarnya digunakan untuk semua instrumen senar, dan semua instrumen dengan keyboard, seperti piano dan keyboard elektrik. Bayangkan saja mengambil peluru dan menggunakannya sebagai pick gitar, lalu menggunakannya untuk menekan tuts piano dan memainkan sebuah lagu.', 'The reading is the same as 引く, which is "to pull." When you play a stringed instrument, you are pulling the string in a direction to make it vibrate and create a sound. So, "to pull" and "to play a stringed instrument" share a reading. It''s a bit more of a stretch for instruments with keyboards, but pianos do at least have strings...', NULL),
  ('00000000-0000-4000-8000-000000006248', 'vocabulary', '言葉遣い', '言葉遣い', 39, 50, 'Jika Anda mencoba mempertimbangkan (遣う) kata-kata Anda (言葉), Anda membuat pilihan kata.', 'The reading is 言葉 and 遣う combined together.', NULL),
  ('00000000-0000-4000-8000-000000006249', 'vocabulary', '小遣い', '小遣い', 39, 51, 'Jika 遣う adalah sesuatu yang mirip dengan "untuk dipertimbangkan" maka "pertimbangan kecil" adalah apa yang akan saya berikan kepada Anda untuk uang belanja Anda. Bisakah saya mendapatkan uang? $50? Tidak, bagaimana dengan pertimbangan yang lebih kecil, mungkin sesuatu yang lebih sesuai dengan tunjangan?', 'The reading is the alternate reading of 小 and 遣う''s reading. Watch out for the rendaku.', NULL),
  ('00000000-0000-4000-8000-000000006250', 'vocabulary', '削除する', '削除する', 39, 52, 'Jika 削除 adalah "penghapusan", maka versi kata kerjanya adalah menghapus.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006251', 'vocabulary', '掲示板', '掲示板', 39, 53, '掲示 adalah pemberitahuan atau tanda. Letakkan ini di papan, dan itu menjadi papan buletin.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006252', 'vocabulary', '渋滞', '渋滞', 39, 54, 'Kemacetan yang pahit adalah ketika Anda terjebak dalam kemacetan. Rasanya pahit, bukan? Mengapa orang tidak bisa mengemudi lebih cepat? Mengapa orang lebih memilih melihat kecelakaan daripada mengemudi? Aku sangat sedih karenanya! Itu sebabnya kata ini adalah kemacetan dan kemacetan lalu lintas.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006253', 'vocabulary', '募集中', '募集中', 39, 55, 'Rekrut dan kumpulkan semua orang ke tengah. Mereka semua berkumpul di sini untuk perekrutan ini karena kami sedang merekrut/sedang merekrut.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006254', 'vocabulary', '戻り道', '戻り道', 39, 56, 'Jika 戻る berarti "kembali" maka Anda kembali melalui jalan asal Anda, Anda mengambil jalan pulang.', 'The reading is the kun''yomi vocab readings of everything. Think 戻る for the 戻り portion.', NULL),
  ('00000000-0000-4000-8000-000000006255', 'vocabulary', '取り戻す', '取り戻す', 39, 57, 'Mengambil dan mengembalikan sesuatu kepada diri sendiri berarti mengambil kembali sesuatu. Kembalikan!', 'The readings come from 取る and 戻す. Combine them to get this.', NULL),
  ('00000000-0000-4000-8000-000000006256', 'vocabulary', '原子爆弾', '原子爆弾', 39, 58, '原子 adalah atom dan 爆弾 adalah bom. Apa itu bom atom? Sebuah bom atom.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006257', 'vocabulary', '足跡', '足跡', 39, 59, 'Jejak kaki adalah jejak kaki.', 'The reading is the kun''yomi vocab readings of the kanji, put together.', NULL),
  ('00000000-0000-4000-8000-000000006258', 'vocabulary', '狙う', '狙う', 39, 60, 'Remember 狙い and how it means "aim"? Make that into a verb, and you have to aim at.', 'The reading comes from 狙い, so if you know that you''ll be able to aim at knowing this word''s reading as well.', NULL),
  ('00000000-0000-4000-8000-000000006259', 'vocabulary', '邦訳', '邦訳', 39, 61, 'Terjemahan negara asal adalah terjemahan ke bahasa negara asal Anda. Karena ini adalah kata dalam bahasa Jepang, terjemahan ini akan menjadi terjemahan ke dalam bahasa Jepang.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006260', 'vocabulary', '邦人', '邦人', 39, 62, 'Orang asal negara adalah rekan senegaranya atau rekan senegaranya (hanya untuk orang Jepang saja). Di Jepang, Anda adalah warga negara Jepang.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006261', 'vocabulary', '連邦', '連邦', 39, 63, 'Bawa serta negara asal Anda ke semua ruang lain yang ingin Anda tambahkan ke grup Anda. Gabungkan mereka untuk membentuk persemakmuran atau federasi.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006262', 'vocabulary', '呼び鈴', '呼び鈴', 39, 64, 'Bel yang akan memanggil Anda ke pintu adalah bel pintu.', 'The reading is 呼ぶ and 鈴''s reading, put together.', NULL),
  ('00000000-0000-4000-8000-000000006263', 'vocabulary', '鈴', '鈴', 39, 65, 'Arti kata ini berasal dari kanji. Itu bel kecil!', 'Since this word is made up of a single kanji, it probably uses the kun''yomi reading. You did not learn this reading, so here''s a mnemonic to help you: 
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000006442', 'vocabulary', '褒美', '褒美', 40, 155, 'Saya memuji Anda atas kecantikan Anda. Aku sangat menyukai kecantikanmu, aku memberimu hadiah... hadiah, pada dasarnya.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006443', 'vocabulary', '褒賞', '褒賞', 40, 156, 'Saya memuji Anda atas apa yang Anda lakukan, jadi inilah hadiah Anda bersamaan dengan pujian saya, sebuah medali!', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006444', 'vocabulary', '透ける', '透ける', 40, 157, 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti transparan dan versi vocab verbanya berarti transparan (karena biasanya orang tidak bisa "mentransparankan" sesuatu).', 'To remember the reading, just think about something that is supposed to not be transparent, but is transparent after you give it to someone for a while. You''re so upset that your (dog/cat/plant/car/etc) is transparent that you sue the guy who was supposed to not make it transparent.', NULL),
  ('00000000-0000-4000-8000-000000006445', 'vocabulary', '透明', '透明', 40, 158, 'Sesuatu yang transparan dan terang sehingga Anda dapat melihatnya adalah transparan.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006446', 'vocabulary', '隣', '隣', 40, 159, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Remember the movie "Tonari (となり) no Totoro"? That is the Tonari.', NULL),
  ('00000000-0000-4000-8000-000000006447', 'vocabulary', '隣家', '隣家', 40, 160, 'Rumah tetangga adalah rumah tetangga. Rumah itu tepat di sebelah rumah kita!', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006448', 'vocabulary', '近隣', '近隣', 40, 161, 'Semua tetangga dekat adalah orang-orang yang tinggal di sekitar Anda dan di dekat Anda. Mereka adalah bagian dari lingkungan sekitar.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006449', 'vocabulary', '隣国', '隣国', 40, 162, 'Negara tetangga adalah negara tetangga. Bagi kami, 隣国 kami di Amerika adalah orang-orang Kanada yang licik... yang selalu menunggu untuk menyerang, saya tahu...', 'This is a jukugo word that uses the on''yomi readings of the kanji. You should be able to read this on your own. Watch out for the rendaku.', NULL),
  ('00000000-0000-4000-8000-000000006450', 'vocabulary', '隣人', '隣人', 40, 163, 'Orang tetangga adalah tetangga.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006451', 'vocabulary', '雅致', '雅致', 40, 164, 'Jika semua yang Anda lakukan elegan, Anda memiliki seni dan selera yang bagus. Begitu banyak keanggunan!', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006452', 'vocabulary', '雅楽', '雅楽', 40, 165, 'Ini sangat elegan dan nyaman. Ini adalah musik istana Jepang, dan itulah yang didengarkan oleh orang-orang istana di Jepang pada masa itu. Anda juga bisa menyebutnya gagaku jika Anda mau.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006453', 'vocabulary', '優雅', '優雅', 40, 166, 'Sesuatu yang unggul dan anggun memiliki banyak keanggunan dan keanggunan.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000007279', 'vocabulary', '背丈', '背丈', 32, 148, 'Someone''s back height is their height. It also refers to their stature.', 'The reading comes from the vocab readings of 背 and 丈, combined together.', NULL),
  ('00000000-0000-4000-8000-000000007471', 'vocabulary', '汚い', '汚い', 36, 132, 'Ini adalah bentuk kata sifat dari 汚, yaitu kotor. Kata ini adalah kata sifat kotor, tapi Anda juga bisa menggunakannya untuk mengatakan hal-hal seperti kotor, busuk, atau najis.', 'The reading is different from the other kun''yomi readings you''ve learned so far with this word. It is きたない. Think of it like you''re saying "来た、な", as in "it came, huh?" What came? A really dirty looking monster, and it''s coming for you.', NULL),
  ('00000000-0000-4000-8000-000000007473', 'vocabulary', '眼鏡', '眼鏡', 34, 152, 'Cermin bola mata adalah sesuatu yang membiaskan dan memfokuskan cahaya ke bola mata Anda dengan cara yang berbeda sehingga Anda dapat melihat lebih baik. Sungguh, benda-benda ini adalah kacamata, bukan cermin mata, tapi benda serupa jika Anda langsung melakukannya. Bayangkan saja seseorang memakai cermin di matanya, dan ketika Anda bertanya untuk apa cermin itu, mereka hanya menjawab itu kacamata.', 'The reading for 眼 is the same as the vocab 眼. The reading for 鏡 is an exception, totally different. It shares a reading with 金 (gold), though, so think of the mirrors on the person''s eyes being made of gold. What nice glasses!
